package writer

import "github.com/PorticoMediaServer/portico/server/internal/store/stmt"

const (
	basicCopyStreamScope   stmt.ID = "scan.basic_stage.copy_stream_scope"
	basicCopyStreamStaged  stmt.ID = "scan.basic_stage.copy_stream_staged"
	basicCopyStreamPresent stmt.ID = "scan.basic_stage.copy_stream_present"
	basicCopyStreamInsert  stmt.ID = "scan.basic_stage.copy_stream_insert"
	basicCopyStreamUpdate  stmt.ID = "scan.basic_stage.copy_stream_update"
	basicCopyBreadthStaged stmt.ID = "scan.basic_stage.copy_breadth_staged"
	basicCopyBreadthParent stmt.ID = "scan.basic_stage.copy_breadth_parent"
	basicCopyBreadthInsert stmt.ID = "scan.basic_stage.copy_breadth_insert"
	basicCopyBreadthUpdate stmt.ID = "scan.basic_stage.copy_breadth_update"
)

// Breadth is physically folded into asset_streams in the native schema. The
// two literal CAS statements never touch core fields, siblings or child keys.
func basicCopyStreamDefinitions() []stmt.Definition {
	i := func(n string) stmt.Param { return stmt.Param{Name: n, Type: stmt.Integer} }
	t := func(n string) stmt.Param { return stmt.Param{Name: n, Type: stmt.Text} }
	defs := []stmt.Definition{
		{ID: basicCopyStreamScope, Kind: stmt.Read, SQL: `SELECT a.info_publication_pending,l.info_pending_change,a.file_size_revision,a.info_invalidation_revision,l.library_id,e.library_id,e.kind,e.retired,a.info_owner_object,a.info_owner_revision,s.id,s.library_id,s.kind FROM catalog_assets AS a INNER JOIN catalog_asset_links AS l ON l.asset_id=a.id INNER JOIN catalog_entities AS e ON e.id=l.entity_id INNER JOIN catalog_subjects AS s ON s.id=e.id WHERE a.id=? AND l.entity_id=? AND l.asset_id=?`, Params: []stmt.Param{i("asset_id"), i("entity_id"), i("linked_asset_id")},
			Plan: stmt.Plan{Hot: true, PrimaryKeys: []string{"a", "l", "e", "s"}, Seeks: []string{"rowid=?", "entity_id=? AND asset_id=?"}}, Cohorts: []stmt.Cohort{{Name: "fenced_retained_ordinary_holder", Bindings: []any{int64(41), int64(31), int64(41)}}}},
		{ID: basicCopyStreamStaged, Kind: stmt.Read, SQL: `SELECT input_ordinal,asset_id,stream_index,type,codec,language,title,channels,channel_layout,is_default,is_forced,color_transfer,color_primaries,detail_json FROM catalog_info_new_streams WHERE change_id=? AND input_ordinal=?`, Params: []stmt.Param{i("change_id"), i("input_ordinal")},
			Plan: stmt.Plan{Hot: true, Indexes: []string{"sqlite_autoindex_catalog_info_new_streams_2"}, Seeks: []string{"change_id=? AND input_ordinal=?"}}, Cohorts: []stmt.Cohort{{Name: "exact_sealed_stream", Bindings: []any{int64(51), int64(0)}}}},
		{ID: basicCopyStreamPresent, Kind: stmt.Read, SQL: `SELECT 1 FROM asset_streams WHERE asset_id=? AND stream_index=?`, Params: []stmt.Param{t("asset_token"), i("stream_index")},
			Plan: stmt.Plan{Hot: true, Indexes: []string{"sqlite_autoindex_asset_streams_1"}, Seeks: []string{"asset_id=? AND stream_index=?"}}, Cohorts: []stmt.Cohort{{Name: "exact_canonical_stream_key", Bindings: []any{"basic-asset", int64(0)}}}},
		{ID: basicCopyStreamInsert, Kind: stmt.Write, SQL: `INSERT INTO asset_streams(asset_id,stream_index,type,codec,language,title,channels,channel_layout,is_default,is_forced,color_transfer,color_primaries,detail_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING asset_id,stream_index,type,codec,language,title,channels,channel_layout,is_default,is_forced,color_transfer,color_primaries,detail_json`, Params: []stmt.Param{t("asset_token"), i("stream_index"), t("type"), t("codec"), t("language"), t("title"), i("channels"), t("channel_layout"), i("is_default"), i("is_forced"), t("color_transfer"), t("color_primaries"), t("detail_json")},
			Plan: stmt.Plan{Hot: true}, Cohorts: []stmt.Cohort{{Name: "first_canonical_stream", Bindings: []any{"basic-asset", int64(0), "video", "h264", "en", "Opening video", int64(0), "", int64(1), int64(0), "bt709", "bt709", "{\"width\":1920}"}}}},
		{ID: basicCopyStreamUpdate, Kind: stmt.Write, SQL: `UPDATE asset_streams SET type=?,codec=?,language=?,title=?,channels=?,channel_layout=?,is_default=?,is_forced=?,color_transfer=?,color_primaries=?,detail_json=? WHERE asset_id=? AND stream_index=? AND type=? AND codec=? AND language=? AND title=? AND channels=? AND channel_layout=? AND is_default=? AND is_forced=? AND color_transfer=? AND color_primaries=? AND detail_json=? RETURNING asset_id,stream_index,type,codec,language,title,channels,channel_layout,is_default,is_forced,color_transfer,color_primaries,detail_json`, Params: []stmt.Param{t("next_type"), t("next_codec"), t("next_language"), t("next_title"), i("next_channels"), t("next_channel_layout"), i("next_is_default"), i("next_is_forced"), t("next_color_transfer"), t("next_color_primaries"), t("next_detail_json"), t("asset_token"), i("stream_index"), t("type"), t("codec"), t("language"), t("title"), i("channels"), t("channel_layout"), i("is_default"), i("is_forced"), t("color_transfer"), t("color_primaries"), t("detail_json")},
			Plan: stmt.Plan{Hot: true, Indexes: []string{"sqlite_autoindex_asset_streams_1"}, Seeks: []string{"asset_id=? AND stream_index=?"}}, Cohorts: []stmt.Cohort{{Name: "replace_exact_core_keep_breadth", Bindings: []any{"video", "h264", "en", "Opening video", int64(0), "", int64(1), int64(0), "bt709", "bt709", "{\"width\":1920}", "basic-asset", int64(0), "video", "h264", "en", "Opening video", int64(0), "", int64(1), int64(0), "bt709", "bt709", "{\"width\":1920}"}}}},
		{ID: basicCopyBreadthStaged, Kind: stmt.Read, SQL: `SELECT input_ordinal,asset_id,stream_index,audio_description,audio_variant,chroma_subsampling,fps_numerator,fps_denominator,frame_rate_mode,interlace_analysis,telecine,dovi_rpu,dovi_base_layer,dovi_metadata_known,dovi_enhancement_type,dovi_cm_version,playback_frames_revision,packet_peak_revision FROM catalog_info_new_stream_breadth WHERE change_id=? AND input_ordinal=?`, Params: []stmt.Param{i("change_id"), i("input_ordinal")},
			Plan: stmt.Plan{Hot: true, Indexes: []string{"sqlite_autoindex_catalog_info_new_stream_breadth_2"}, Seeks: []string{"change_id=? AND input_ordinal=?"}}, Cohorts: []stmt.Cohort{{Name: "exact_sealed_breadth", Bindings: []any{int64(51), int64(0)}}}},
		{ID: basicCopyBreadthParent, Kind: stmt.Read, SQL: `SELECT stream_index,type,has_asset_stream_breadth FROM asset_streams WHERE asset_id=? AND stream_index=?`, Params: []stmt.Param{t("asset_token"), i("stream_index")},
			Plan: stmt.Plan{Hot: true, Indexes: []string{"sqlite_autoindex_asset_streams_1"}, Seeks: []string{"asset_id=? AND stream_index=?"}}, Cohorts: []stmt.Cohort{{Name: "actual_stream_parent", Bindings: []any{"basic-asset", int64(0)}}}},
		{ID: basicCopyBreadthInsert, Kind: stmt.Write, SQL: `UPDATE asset_streams SET has_asset_stream_breadth=?,breadth_audio_description=?,breadth_audio_variant=?,breadth_chroma_subsampling=?,breadth_fps_numerator=?,breadth_fps_denominator=?,breadth_frame_rate_mode=?,breadth_interlace_analysis=?,breadth_telecine=?,breadth_dovi_rpu=?,breadth_dovi_base_layer=?,breadth_dovi_metadata_known=?,breadth_dovi_enhancement_type=?,breadth_dovi_cm_version=?,breadth_playback_frames_revision=?,breadth_packet_peak_revision=? WHERE asset_id=? AND stream_index=? AND has_asset_stream_breadth=? RETURNING asset_id,stream_index,has_asset_stream_breadth,breadth_audio_description,breadth_audio_variant,breadth_chroma_subsampling,breadth_fps_numerator,breadth_fps_denominator,breadth_frame_rate_mode,breadth_interlace_analysis,breadth_telecine,breadth_dovi_rpu,breadth_dovi_base_layer,breadth_dovi_metadata_known,breadth_dovi_enhancement_type,breadth_dovi_cm_version,breadth_playback_frames_revision,breadth_packet_peak_revision`, Params: []stmt.Param{i("next_present"), i("next_audio_description"), t("next_audio_variant"), t("next_chroma_subsampling"), i("next_fps_numerator"), i("next_fps_denominator"), t("next_frame_rate_mode"), t("next_interlace_analysis"), i("next_telecine"), i("next_dovi_rpu"), i("next_dovi_base_layer"), i("next_dovi_metadata_known"), t("next_dovi_enhancement_type"), t("next_dovi_cm_version"), t("next_playback_frames_revision"), t("next_packet_peak_revision"), t("asset_token"), i("stream_index"), i("expected_present")},
			Plan: stmt.Plan{Hot: true, Indexes: []string{"sqlite_autoindex_asset_streams_1"}, Seeks: []string{"asset_id=? AND stream_index=?"}}, Cohorts: []stmt.Cohort{{Name: "first_logical_breadth", Bindings: []any{int64(1), int64(0), "main", "4:2:0", int64(24000), int64(1001), "constant", "progressive", int64(0), int64(1), int64(1), int64(1), "mel", "4.0", "frames:31", "peak:31", "basic-asset", int64(0), int64(0)}}}},
		{ID: basicCopyBreadthUpdate, Kind: stmt.Write, SQL: `UPDATE asset_streams SET has_asset_stream_breadth=?,breadth_audio_description=?,breadth_audio_variant=?,breadth_chroma_subsampling=?,breadth_fps_numerator=?,breadth_fps_denominator=?,breadth_frame_rate_mode=?,breadth_interlace_analysis=?,breadth_telecine=?,breadth_dovi_rpu=?,breadth_dovi_base_layer=?,breadth_dovi_metadata_known=?,breadth_dovi_enhancement_type=?,breadth_dovi_cm_version=?,breadth_playback_frames_revision=?,breadth_packet_peak_revision=? WHERE asset_id=? AND stream_index=? AND has_asset_stream_breadth=? AND breadth_audio_description=? AND breadth_audio_variant=? AND breadth_chroma_subsampling=? AND breadth_fps_numerator=? AND breadth_fps_denominator=? AND breadth_frame_rate_mode=? AND breadth_interlace_analysis=? AND breadth_telecine=? AND breadth_dovi_rpu=? AND breadth_dovi_base_layer=? AND breadth_dovi_metadata_known=? AND breadth_dovi_enhancement_type=? AND breadth_dovi_cm_version=? AND breadth_playback_frames_revision=? AND breadth_packet_peak_revision=? RETURNING asset_id,stream_index,has_asset_stream_breadth,breadth_audio_description,breadth_audio_variant,breadth_chroma_subsampling,breadth_fps_numerator,breadth_fps_denominator,breadth_frame_rate_mode,breadth_interlace_analysis,breadth_telecine,breadth_dovi_rpu,breadth_dovi_base_layer,breadth_dovi_metadata_known,breadth_dovi_enhancement_type,breadth_dovi_cm_version,breadth_playback_frames_revision,breadth_packet_peak_revision`, Params: []stmt.Param{i("next_present"), i("next_audio_description"), t("next_audio_variant"), t("next_chroma_subsampling"), i("next_fps_numerator"), i("next_fps_denominator"), t("next_frame_rate_mode"), t("next_interlace_analysis"), i("next_telecine"), i("next_dovi_rpu"), i("next_dovi_base_layer"), i("next_dovi_metadata_known"), t("next_dovi_enhancement_type"), t("next_dovi_cm_version"), t("next_playback_frames_revision"), t("next_packet_peak_revision"), t("asset_token"), i("stream_index"), i("expected_present"), i("audio_description"), t("audio_variant"), t("chroma_subsampling"), i("fps_numerator"), i("fps_denominator"), t("frame_rate_mode"), t("interlace_analysis"), i("telecine"), i("dovi_rpu"), i("dovi_base_layer"), i("dovi_metadata_known"), t("dovi_enhancement_type"), t("dovi_cm_version"), t("playback_frames_revision"), t("packet_peak_revision")},
			Plan: stmt.Plan{Hot: true, Indexes: []string{"sqlite_autoindex_asset_streams_1"}, Seeks: []string{"asset_id=? AND stream_index=?"}}, Cohorts: []stmt.Cohort{{Name: "replace_exact_breadth_keep_core", Bindings: []any{int64(1), int64(0), "main", "4:2:0", int64(24000), int64(1001), "constant", "progressive", int64(0), int64(1), int64(1), int64(1), "mel", "4.0", "frames:31", "peak:31", "basic-asset", int64(0), int64(1), int64(0), "main", "4:2:0", int64(24000), int64(1001), "constant", "progressive", int64(0), int64(1), int64(1), int64(1), "mel", "4.0", "frames:31", "peak:31"}}}},
	}
	for n := range defs {
		defs[n].Owner = "store/writer Basic domain"
		defs[n].CallSites = []string{"store/writer/basic_copy_stream.go"}
	}
	return defs
}
